solution.solution.c:
#include <ctype.h>
#include <string.h>

const char *skip_spaces(const char *s)
{
    while (*s != '\0' && isspace((unsigned char)*s)) s++;
    return s;
}

void trim_end(char *s)
{
    size_t n = strlen(s);
    while (n > 0 && isspace((unsigned char)s[n - 1])) {
        n--;
    }
    s[n] = '\0';
}

char *trim(char *s)
{
    trim_end(s);
    while (*s != '\0' && isspace((unsigned char)*s)) s++;
    return s;
}

int count_in(const char *s, const char *set)
{
    int count = 0;
    for (; *s != '\0'; s++) {
        if (strchr(set, *s) != NULL) count++;
    }
    return count;
}

unitTests:
TEST("skipping spaces") { const char *s = "   hi"; CHECK(skip_spaces(s) == s + 3); CHECK_STR(skip_spaces("\t\n x"), "x"); CHECK_STR(skip_spaces(""), ""); CHECK_STR(skip_spaces("    "), ""); }
TEST("trimming the end") { char a[] = "hello   "; trim_end(a); CHECK_STR(a, "hello"); char b[] = "  keep front \n"; trim_end(b); CHECK_STR(b, "  keep front"); char c[] = "   "; trim_end(c); CHECK_STR(c, ""); char d[] = ""; trim_end(d); CHECK_STR(d, ""); }
TEST("trimming both ends") { char a[] = "  both sides  "; char *t = trim(a); CHECK_STR(t, "both sides"); CHECK(t == a + 2); char b[] = "none"; CHECK(trim(b) == b); }
TEST("counting characters from a set") { CHECK_EQ(count_in("hello", "lo"), 3); CHECK_EQ(count_in("hello", ""), 0); CHECK_EQ(count_in("a,b;c", ",;"), 2); CHECK_EQ(count_in("", "abc"), 0); }

